    w = len(grid[0]) if h else 0

    visited = [[False] * w for _ in range(h)]
    rects = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 9 and not visited[r][c]:
                stack = [(r, c)]
                visited[r][c] = True
                cells = []
                while stack:
                    x, y = stack.pop()
                    cells.append((x, y))
                    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < h and 0 <= ny < w and not visited[nx][ny] and grid[nx][ny] == 9:
                            visited[nx][ny] = True
                            stack.append((nx, ny))

                r0 = min(x for x, _ in cells)
                r1 = max(x for x, _ in cells)
                c0 = min(y for _, y in cells)
                c1 = max(y for _, y in cells)
                rects.append((r0, r1, c0, c1))

    out = [[0] * w for _ in range(h)]

    # Paint vertical tails (1)
    for r0, r1, c0, c1 in rects:
        width = c1 - c0 + 1
        t = width // 2
        start_row = r1 + t + 1
        for r in range(start_row, h):
            for c in range(c0, c1 + 1):
                if out[r][c] < 1:
                    out[r][c] = 1

    # Paint expanded border regions (3)
    for r0, r1, c0, c1 in rects:
        width = c1 - c0 + 1
        t = width // 2
        rr0 = max(0, r0 - t)
        rr1 = min(h - 1, r1 + t)
        cc0 = max(0, c0 - t)
        cc1 = min(w - 1, c1 + t)
        for r in range(rr0, rr1 + 1):
            for c in range(cc0, cc1 + 1):
                if not (r0 <= r <= r1 and c0 <= c <= c1):
                    if out[r][c] < 3:
                        out[r][c] = 3

    # Paint original rectangles (9)
    for r0, r1, c0, c1 in rects:
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                out[r][c] = 9

    return out

